mapper.select:
select
    date_format(str_to_date(left(p.pest_a, 10), '%Y-%m-%d'), '%m-%d') as dateLabel,
    ifnull(sum(p.pest_total_count), 0) as pestCount
from xwq_ai_pest p
left join xwq_ai_image img on img.image_id = p.image_id
left join xwq_ai_record r on r.record_id = p.record_id

    p.pest_a is not null
    and p.pest_a != ''
    and str_to_date(left(p.pest_a, 10), '%Y-%m-%d') >= date_sub(curdate(), interval 6 day)
     and coalesce(r.park_id, img.park_id) = #{parkId}
     and coalesce(r.plot_id, img.plot_id) = #{areaId}
     and img.image_b = #{locationId}
     and img.device_id = #{deviceId}
     and p.pest_name = #{pestName}

group by date_format(str_to_date(left(p.pest_a, 10), '%Y-%m-%d'), '%m-%d')
order by min(str_to_date(left(p.pest_a, 10), '%Y-%m-%d')) asc

mapper.update:
update xwq_ai_pest
record_id = #{recordId}, image_id = #{imageId}, pest_name = #{pestName}, pest_code = #{pestCode}, pest_crop = #{pestCrop}, pest_confidence = #{pestConfidence}, pest_count = #{pestCount}, pest_total_count = #{pestTotalCount}, pest_result = #{pestResult}, pest_advice = #{pestAdvice}, pest_result_img_url = #{pestResultImgUrl}, bbox_json = #{bboxJson}, is_warning = #{isWarning}, warning_level = #{warningLevel}, pest_a = #{pestA}, pest_b = #{pestB}, pest_c = #{pestC}, pest_d = #{pestD}, pest_e = #{pestE}, pest_f = #{pestF}, pest_g = #{pestG}, pest_h = #{pestH}, pest_i = #{pestI}, pest_j = #{pestJ},
where pest_id = #{pestId}
